# Check if 607, 53, and 71 are prime (they are, but good practice to verify)
import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

primes = [5, 13, 607, 53, 71]
for p in primes:
    print(f"{p} is prime: {is_prime(p)}")

